    cs=[c for c in range(C) if g[r][c]==9]
    if len(cs)>=3:
        for c in range(min(cs),max(cs)+1):
            if g[r][c]==3:g[r][c]=2
for c in range(C):
    rs=[r for r in range(R) if g[r][c]==9]
